input.newString:
import { useEffect } from 'react';

export default function BlogHeader() {
  useEffect(() => {
    const link = document.createElement('link');
    link.href = 'https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;700&family=Roboto:wght@400;500&display=swap';
    link.rel = 'stylesheet';
    document.head.appendChild(link);

    return () => {
      document.head.removeChild(link);
    };
  }, []);

  return (
    <header>
      <h1 style={{ fontFamily: '"Playfair Display", serif' }}>My Personal Blog</h1>
      <p style={{ fontFamily: '"Roboto", sans-serif' }}>Thoughts, ideas, and musings</p>
    </header>
  );
}

